&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-5-2-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Champion engineering culture transformation, fostering genuine collaboration across development, &lt;/span&gt;&lt;span class=&quot;text-only text-with-abbreviation text-with-abbreviation-bottomline&quot;&gt;QA&lt;/span&gt;&lt;span class=&quot;text-only&quot;&gt;, and operations — breaking down process silos rather than reinforcing them&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;div class=&quot;rich-text-paragraph&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-6&quot;&gt;&lt;strong&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-6-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Platform Engineering &amp;amp; Infrastructure&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/div&gt;
