&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-7-0&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-7-0-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Lead the development of an Internal Developer Platform (IDP) to reduce cognitive load for engineers and improve the overall developer experience (DevEx)&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
